from itertools import permutations
cls={'R':5,'S':5,'P':4,'T':4}; boy={'R':1,'S':0,'P':1,'T':0}
sols=[]
def go(alive,games):
    if len(games)==3:
        ws=[w for w,l in games]; c5=sum(cls[w]==5 for w in ws)
        same=[cls[w]==cls[l] for w,l in games]
        if same==[True,False,False] and c5>3-c5 and sum(boy[w] for w in ws)==2:
            sols.append((games,alive))
        return
    for w,l in permutations(alive,2):
        go([x for x in alive if x!=l],games+[(w,l)])
go(list('RSPT'),[])
print(sols)  # [([('R','S'),('R','P'),('T','R')], ['T'])] -> Tanvi
